// Direct PDF layout drawing engine using jsPDF coordinates in mm.
// Self-contained Unicode font support for Be Vietnam Pro to render Vietnamese characters correctly.

(function() {
    const BeVietnamProRegularB64 = "";
    const BeVietnamProBoldB64 = "";

    // Export function to global scope
    window.exportDesignPdf = function(designData) {
        return new Promise(async (resolve, reject) => {
            try {
                const { jsPDF } = window.jspdf ? window.jspdf : window;
                const pdf = new jsPDF({
                    orientation: 'portrait',
                    unit: 'mm',
                    format: 'a4'
                });

                // Register Unicode fonts
                pdf.addFileToVFS('BeVietnamPro-Regular.ttf', BeVietnamProRegularB64);
                pdf.addFont('BeVietnamPro-Regular.ttf', 'BeVietnamPro', 'normal');
                pdf.addFileToVFS('BeVietnamPro-Bold.ttf', BeVietnamProBoldB64);
                pdf.addFont('BeVietnamPro-Bold.ttf', 'BeVietnamPro', 'bold');
                pdf.setFont('BeVietnamPro', 'normal');

                console.log("PDF engine initialized with Be Vietnam Pro Unicode support.");

                // Asynchronously load the Front and Back canvas images to verify dimensions
                const loadImg = (src) => {
                    return new Promise((res) => {
                        if (!src) return res(null);
                        const img = new Image();
                        img.onload = () => res(img);
                        img.onerror = () => res(null);
                        img.src = src;
                    });
                };

                const [loadedFront, loadedBack] = await Promise.all([
                    loadImg(designData.imgFront),
                    loadImg(designData.imgBack)
                ]);

                // ── HELPER STYLING & DRAWING FUNCTIONS ──────────────────────────
                function hexToRgb(hex) {
                    const r = parseInt(hex.slice(1, 3), 16);
                    const g = parseInt(hex.slice(3, 5), 16);
                    const b = parseInt(hex.slice(5, 7), 16);
                    return { r, g, b };
                }
                function setPdfFillColor(hex) {
                    const rgb = hexToRgb(hex);
                    pdf.setFillColor(rgb.r, rgb.g, rgb.b);
                }
                function setPdfDrawColor(hex) {
                    const rgb = hexToRgb(hex);
                    pdf.setDrawColor(rgb.r, rgb.g, rgb.b);
                }
                function setPdfTextColor(hex) {
                    const rgb = hexToRgb(hex);
                    pdf.setTextColor(rgb.r, rgb.g, rgb.b);
                }

                function drawText(pdfInstance, text, x, y, options = {}) {
                    let textStr = "";
                    if (text !== undefined && text !== null && !(typeof text === 'number' && isNaN(text))) {
                        textStr = String(text);
                    }
                    if (textStr === "undefined" || textStr === "null" || textStr === "NaN") {
                        textStr = "";
                    }
                    
                    const fontStyle = options.bold ? 'bold' : 'normal';
                    pdfInstance.setFont('BeVietnamPro', fontStyle);
                    
                    const fontSize = options.fontSize || pdfInstance.getFontSize();
                    pdfInstance.setFontSize(fontSize);
                    
                    if (options.color) {
                        setPdfTextColor(options.color);
                    } else {
                        setPdfTextColor('#0f172a');
                    }
                    
                    const align = options.align || 'left';
                    const angle = options.angle || 0;
                    const maxWidth = options.maxWidth || 0;
                    
                    const textOptions = { align: align };
                    if (angle) {
                        textOptions.angle = angle;
                    }
                    
                    if (maxWidth > 0) {
                        let textWidth = pdfInstance.getTextWidth(textStr);
                        let currentFontSize = fontSize;
                        if (textWidth > maxWidth) {
                            // Try reducing font size by 5% first
                            currentFontSize = fontSize * 0.95;
                            pdfInstance.setFontSize(currentFontSize);
                            textWidth = pdfInstance.getTextWidth(textStr);
                            if (textWidth > maxWidth) {
                                // If still too wide, try reducing to 90%
                                currentFontSize = fontSize * 0.90;
                                pdfInstance.setFontSize(currentFontSize);
                            }
                        }
                        
                        let lines = pdfInstance.splitTextToSize(textStr, maxWidth);
                        if (lines.length > 2) {
                            lines = lines.slice(0, 2);
                        }
                        
                        const currentLineHeight = (options.lineHeight || 1.2) * (currentFontSize * 0.352778);
                        let currentY = y;
                        if (lines.length > 1) {
                            const totalHeight = (lines.length - 1) * currentLineHeight;
                            currentY = y - (totalHeight / 2) + (currentFontSize * 0.352778 * 0.2);
                        }
                        
                        lines.forEach((line) => {
                            pdfInstance.text(line, x, currentY, textOptions);
                            currentY += currentLineHeight;
                        });
                        
                        pdfInstance.setFontSize(fontSize); // restore original
                        return currentY - currentLineHeight;
                    } else {
                        pdfInstance.text(textStr, x, y, textOptions);
                        return y;
                    }
                }

                function drawBlock(title, x, y, w, h) {
                    pdf.setLineWidth(0.3);
                    setPdfDrawColor('#d9e2ec');
                    pdf.setFillColor(255, 255, 255);
                    pdf.roundedRect(x, y, w, h, 2, 2, 'FD');

                    drawText(pdf, title, x + 4, y + 6, { bold: true, fontSize: 8.5, color: '#0088c9' });

                    // divider line
                    setPdfDrawColor('#e2e8f0');
                    pdf.setLineWidth(0.15);
                    pdf.line(x + 4, y + 8, x + w - 4, y + 8);
                }

                function fitImageInsideBox(imgW, imgH, boxW, boxH) {
                    const imgRatio = imgW / imgH;
                    const boxRatio = boxW / boxH;
                    let w, h, xOffset, yOffset;
                    if (imgRatio > boxRatio) {
                        w = boxW;
                        h = boxW / imgRatio;
                        xOffset = 0;
                        yOffset = (boxH - h) / 2;
                    } else {
                        h = boxH;
                        w = boxH * imgRatio;
                        xOffset = (boxW - w) / 2;
                        yOffset = 0;
                    }
                    return { w, h, x: xOffset, y: yOffset };
                }

                // ── 1. WATERMARK BACKGROUND (Drawn first under content) ───────
                drawText(pdf, "ĐỒNG PHỤC MRS LINH", 105, 150, { bold: true, fontSize: 32, color: '#f8fafc', align: 'center', angle: 30 });

                // ── 2. HEADER BLOCK (y: 10 to 32) ─────────────────────────────
                // Brand Left group
                drawText(pdf, "MRS LINH", 10, 16, { bold: true, fontSize: 18, color: '#0088c9' });
                drawText(pdf, "U  N  I  F  O  R  M", 10, 20, { bold: true, fontSize: 7.5, color: '#0f172a' });
                drawText(pdf, "ĐỒNG PHỤC CHUYÊN NGHIỆP", 10, 23.2, { fontSize: 5.2, color: '#64748b' });

                // Vertical Divider Line
                setPdfDrawColor('#cbd5e1');
                pdf.setLineWidth(0.2);
                pdf.line(42, 11, 42, 29);

                // Brand details next to divider
                drawText(pdf, "CÔNG TY TNHH DV TM ĐT ĐỒNG PHỤC MRS LINH", 45, 14, { bold: true, fontSize: 7.5, color: '#0f172a' });
                drawText(pdf, "📍 Địa chỉ: 16/6 Lưu Trọng Lư, Quy Nhơn, Gia Lai", 45, 18, { fontSize: 6.5, color: '#475569' });
                drawText(pdf, "📞 SĐT/Zalo: 0934.975.913", 45, 22, { fontSize: 6.5, color: '#475569' });
                drawText(pdf, "✉️ mrslinh@inaodongphucmrslinh.com", 45, 26, { bold: true, fontSize: 6.5, color: '#0088c9' });

                // Document Title Right group
                drawText(pdf, "BẢNG MÔ TẢ SẢN PHẨM", 200, 15, { bold: true, fontSize: 15, color: '#0088c9', align: 'right' });
                drawText(pdf, `Mã hồ sơ: ML-${designData.recordCode || '810834'} | TRANG 1/1`, 200, 19, { fontSize: 7, color: '#475569', align: 'right' });
                drawText(pdf, "Hệ thống 3D Mrs Linh", 200, 22, { fontSize: 6.5, color: '#94a3b8', align: 'right' });

                // Top Line Blue Accent
                pdf.setLineWidth(1.0);
                setPdfDrawColor('#0088c9');
                pdf.line(10, 31, 200, 31);

                // ── 3. CUSTOMER DETAILS BAR (y: 36 to 56) ─────────────────────
                pdf.setLineWidth(0.3);
                setPdfDrawColor('#d9e2ec');
                pdf.setFillColor(248, 250, 252); // #f8fafc slate background
                pdf.roundedRect(10, 36, 190, 20, 2, 2, 'FD');

                // Customer contact
                drawText(pdf, "THÔNG TIN KHÁCH HÀNG", 14, 41, { bold: true, fontSize: 7.5, color: '#d60000' });
                drawText(pdf, designData.fullname, 14, 46, { bold: true, fontSize: 9, color: '#0f172a' });
                drawText(pdf, `Số điện thoại / Zalo: ${designData.phone}`, 14, 51, { fontSize: 7.5, color: '#475569' });

                // Creator & Status (Right)
                drawText(pdf, "THỜI GIAN KHỞI TẠO", 196, 41, { bold: true, fontSize: 7.5, color: '#64748b', align: 'right' });
                drawText(pdf, designData.date || new Date().toLocaleDateString('vi-VN'), 196, 46, { fontSize: 8, color: '#475569', align: 'right' });
                drawText(pdf, "Trạng thái: Đã duyệt phác thảo 3D", 196, 51, { bold: true, fontSize: 7.5, color: '#0088c9', align: 'right' });

                // ── 4. LEFT COLUMN BLOCKS (x: 10, y: 62, width: 78) ────────────
                
                // Block 1: SỐ LƯỢNG ĐẶT HÀNG
                const sizeQuantities = designData.sizeQuantities || [];
                const numRows = Math.max(1, sizeQuantities.length);
                const block1Height = 11 + 5 + (numRows * 5) + 5 + 3; // 24 + 5*numRows

                drawBlock("SỐ LƯỢNG ĐẶT HÀNG", 10, 62, 78, block1Height);

                // Table Header Block
                pdf.setFillColor(15, 23, 42); // dark navy #0f172a
                pdf.rect(14, 72, 70, 5, 'F');

                drawText(pdf, "Form", 15.1, 75.5, { bold: true, fontSize: 7, color: '#ffffff', maxWidth: 12.5 });
                drawText(pdf, "Size", 34.25, 75.5, { bold: true, fontSize: 7, color: '#ffffff', align: 'center', maxWidth: 9.5 });
                drawText(pdf, "Thông Số Chuẩn", 40.5, 75.5, { bold: true, fontSize: 7, color: '#ffffff', maxWidth: 29.5 });
                drawText(pdf, "Số Lượng", 82.9, 75.5, { bold: true, fontSize: 7, color: '#ffffff', align: 'right', maxWidth: 12.5 });

                // Rows listing sizes
                pdf.setLineWidth(0.15);
                setPdfDrawColor('#e2e8f0');

                sizeQuantities.forEach((item, idx) => {
                    const rowY = 77 + (idx * 5);
                    
                    if (idx % 2 === 1) {
                        pdf.setFillColor(248, 250, 252);
                        pdf.rect(14, rowY, 70, 5, 'F');
                    }

                    pdf.line(14, rowY + 5, 84, rowY + 5);

                    // Form label styling
                    const isFemale = item.form.includes('Nữ');
                    drawText(pdf, item.form, 15.1, rowY + 3.5, { bold: true, fontSize: 6.5, color: isFemale ? '#ec4899' : '#0284c7', maxWidth: 12.5 });
                    drawText(pdf, item.size, 34.25, rowY + 3.5, { bold: true, fontSize: 6.5, color: '#1e293b', align: 'center', maxWidth: 9.5 });
                    drawText(pdf, item.guide, 40.5, rowY + 3.5, { fontSize: 6, color: '#64748b', maxWidth: 29.5 });
                    drawText(pdf, `${item.qty} chiếc`, 82.9, rowY + 3.5, { bold: true, fontSize: 6.5, color: '#0284c7', align: 'right', maxWidth: 12.5 });
                });

                // Summary Row
                const totalRowY = 77 + (numRows * 5);
                pdf.setFillColor(241, 245, 249);
                pdf.rect(14, totalRowY, 70, 5, 'F');
                pdf.line(14, totalRowY, 84, totalRowY);
                pdf.line(14, totalRowY + 5, 84, totalRowY + 5);

                drawText(pdf, "TỔNG CỘNG SỐ LƯỢNG MẪU", 15.1, totalRowY + 3.5, { bold: true, fontSize: 7, color: '#0f172a', maxWidth: 54 });
                drawText(pdf, `${designData.totalQty} chiếc`, 82.9, totalRowY + 3.5, { bold: true, fontSize: 7, color: '#d60000', align: 'right', maxWidth: 14 });

                // Block 2: ĐẶC TẢ PHỐI MÀU & CHI TIẾT
                const block2Y = 62 + block1Height + 4;
                const colorSpecs = designData.colorSpecs || [];
                const pocketSpecs = designData.pocketSpecs || [];
                const reflectiveSpecs = designData.reflectiveSpecs || [];
                const hasPockets = pocketSpecs.length > 0;
                const hasReflective = reflectiveSpecs.length > 0;

                // Calculate dynamic specs block height by measuring wraps
                let totalSpecsHeight = 0;
                colorSpecs.forEach((item) => {
                    pdf.setFont('BeVietnamPro', 'bold');
                    pdf.setFontSize(6.5);
                    const labelStr = (item.label === undefined || item.label === null) ? "" : String(item.label);
                    const labelLines = pdf.splitTextToSize(labelStr, 28);
                    
                    pdf.setFont('BeVietnamPro', 'normal');
                    pdf.setFontSize(6.5);
                    const valueStr = (item.value === undefined || item.value === null) ? "" : String(item.value);
                    const valueLines = pdf.splitTextToSize(valueStr, 35);
                    
                    const numLines = Math.max(labelLines.length, valueLines.length);
                    totalSpecsHeight += numLines * 3.2; // 3.2mm per line
                });

                const block2Height = 12 + 4 + totalSpecsHeight + (hasPockets ? 5 : 0) + (hasReflective ? 5 : 0) + 4;

                drawBlock("ĐẶC TẢ PHỐI MÀU & CHI TIẾT", 10, block2Y, 78, block2Height);

                drawText(pdf, `Mẫu sản phẩm: ${designData.productName}`, 14, block2Y + 13, { bold: true, fontSize: 7.5, color: '#0284c7', maxWidth: 70 });

                pdf.setLineWidth(0.15);
                setPdfDrawColor('#f1f5f9');

                let currentSpecY = block2Y + 17;
                colorSpecs.forEach((item, idx) => {
                    pdf.setFont('BeVietnamPro', 'bold');
                    pdf.setFontSize(6.5);
                    const labelStr = (item.label === undefined || item.label === null) ? "" : String(item.label);
                    const labelLines = pdf.splitTextToSize(labelStr, 28);
                    
                    pdf.setFont('BeVietnamPro', 'normal');
                    pdf.setFontSize(6.5);
                    const valueStr = (item.value === undefined || item.value === null) ? "" : String(item.value);
                    const valueLines = pdf.splitTextToSize(valueStr, 35);
                    
                    const numLines = Math.max(labelLines.length, valueLines.length);
                    const rowHeight = numLines * 3.2;

                    pdf.line(14, currentSpecY + rowHeight, 84, currentSpecY + rowHeight);

                    if (item.colorHex) {
                        pdf.setLineWidth(0.2);
                        setPdfDrawColor('#cbd5e1');
                        const rgb = hexToRgb(item.colorHex);
                        pdf.setFillColor(rgb.r, rgb.g, rgb.b);
                        const boxY = currentSpecY + (rowHeight - 2.2) / 2;
                        pdf.roundedRect(14, boxY, 2.2, 2.2, 0.4, 0.4, 'FD');
                    }

                    const textY = currentSpecY + 0.5;
                    drawText(pdf, item.label, 18.5, textY, { bold: true, fontSize: 6.5, color: '#475569', maxWidth: 28 });
                    drawText(pdf, item.value, 82, textY, { fontSize: 6.5, color: '#0f172a', align: 'right', maxWidth: 35 });
                    
                    currentSpecY += rowHeight;
                });

                let nextY = currentSpecY;
                if (hasPockets) {
                    drawText(pdf, "📂 Cấu hình túi:", 14, nextY + 3.2, { bold: true, fontSize: 6.5, color: '#475569' });
                    drawText(pdf, pocketSpecs.join(', '), 32, nextY + 3.2, { fontSize: 6.5, color: '#0f172a', maxWidth: 50 });
                    nextY += 5;
                }

                if (hasReflective) {
                    drawText(pdf, "⚡ Phản quang:", 14, nextY + 3.2, { bold: true, fontSize: 6.5, color: '#475569' });
                    drawText(pdf, reflectiveSpecs.join(', '), 32, nextY + 3.2, { fontSize: 6.5, color: '#0f172a', maxWidth: 50 });
                }

                // Block 3: XÁC NHẬN THIẾT KẾ 3D (Bottom left column y: 250 to 278)
                pdf.setLineWidth(0.3);
                setPdfDrawColor('#cbd5e1');
                pdf.setFillColor(248, 250, 252);
                pdf.roundedRect(10, 250, 78, 28, 2, 2, 'FD');

                // Customer Half
                drawText(pdf, "ĐẠI DIỆN KHÁCH HÀNG", 29.5, 255.5, { bold: true, fontSize: 7.5, color: '#0f172a', align: 'center' });
                drawText(pdf, "(Ký, ghi rõ họ tên & đóng dấu)", 29.5, 258.5, { fontSize: 6, color: '#64748b', align: 'center' });

                // Signature placeholder dotted line
                pdf.setLineWidth(0.25);
                setPdfDrawColor('#cbd5e1');
                pdf.setLineDashPattern([0.8, 0.8], 0);
                pdf.line(16, 271, 43, 271);
                pdf.setLineDashPattern([], 0); // Restore solid lines

                // Mrs Linh Half
                drawText(pdf, "ĐỒNG PHỤC MRS LINH", 68.5, 255.5, { bold: true, fontSize: 7.5, color: '#0088c9', align: 'center' });
                drawText(pdf, "(Hệ thống duyệt tự động qua Zalo)", 68.5, 258.5, { fontSize: 6, color: '#64748b', align: 'center' });
                drawText(pdf, "ĐÃ XÁC NHẬN THIẾT KẾ 3D", 68.5, 271, { bold: true, fontSize: 7.5, color: '#0088c9', align: 'center' });


                // ── 5. RIGHT COLUMN BLOCKS (x: 94, y: 62, width: 106) ───────────
                
                // Block 1: Front View Card
                pdf.setLineWidth(0.3);
                setPdfDrawColor('#d9e2ec');
                pdf.setFillColor(255, 255, 255);
                pdf.roundedRect(94, 62, 106, 76, 2, 2, 'FD');

                if (loadedFront) {
                    const fitFront = fitImageInsideBox(loadedFront.width, loadedFront.height, 98, 56);
                    pdf.addImage(loadedFront, 'PNG', 94 + 4 + fitFront.x, 62 + 3 + fitFront.y, fitFront.w, fitFront.h);
                }

                // Label Badge Pill Front
                pdf.setFillColor(224, 242, 254);
                pdf.roundedRect(124, 131, 46, 5, 1, 1, 'F');
                drawText(pdf, "MẶT TRƯỚC (FRONT VIEW)", 147, 134.5, { bold: true, fontSize: 6.5, color: '#0284c7', align: 'center' });

                // Block 2: Back View Card
                pdf.setFillColor(255, 255, 255);
                pdf.roundedRect(94, 142, 106, 76, 2, 2, 'FD');

                if (loadedBack) {
                    const fitBack = fitImageInsideBox(loadedBack.width, loadedBack.height, 98, 56);
                    pdf.addImage(loadedBack, 'PNG', 94 + 4 + fitBack.x, 142 + 3 + fitBack.y, fitBack.w, fitBack.h);
                }

                // Label Badge Pill Back
                pdf.setFillColor(224, 242, 254);
                pdf.roundedRect(124, 211, 46, 5, 1, 1, 'F');
                drawText(pdf, "MẶT SAU (BACK VIEW)", 147, 214.5, { bold: true, fontSize: 6.5, color: '#0284c7', align: 'center' });

                // Block 3: Logo / Pattern characteristics spec board (y: 222 to 278)
                drawBlock("ĐẶC TÍNH LOGO / HỌA TIẾT", 94, 222, 106, 56);

                const logos = designData.logos || [];
                const patterns = designData.patterns || [];
                const texts = designData.texts || [];

                if (logos.length === 0 && patterns.length === 0 && texts.length === 0) {
                    drawText(pdf, "Đặc tính logo / họa tiết: chưa gắn vào thiết kế", 98, 237, { fontSize: 7.5, color: '#64748b' });
                } else {
                    pdf.setLineWidth(0.15);
                    setPdfDrawColor('#cbd5e1');

                    const itemsToDraw = [];
                    logos.forEach((logo, idx) => {
                        let logoName = "";
                        if (logo.file && logo.file.name) {
                            logoName = logo.file.name;
                        } else if (logo.name) {
                            logoName = logo.name;
                        } else if (logo.title) {
                            logoName = logo.title;
                        }
                        
                        if (logoName) {
                            logoName = logoName.replace(/\.[^/.]+$/, ""); // strip extension
                        }
                        
                        let title = "";
                        const positionText = (logo.position && logo.position !== "undefined" && logo.position !== "null") ? logo.position : "";
                        
                        if (logoName) {
                            if (positionText) {
                                title = `Logo: ${logoName} (${positionText})`;
                            } else {
                                title = `Logo: ${logoName}`;
                            }
                        } else {
                            if (positionText) {
                                title = `Logo Cố Định: ${positionText}`;
                            } else {
                                title = `Logo Tự Do #${idx + 1}`;
                            }
                        }
                        
                        let printStyleText = "In PET sắc nét";
                        if (logo.printStyle === 'theu') {
                            printStyleText = "Thêu vi tính satin";
                        }
                        
                        const scaleText = logo.scale ? `${logo.scale}px` : "";
                        let subtext = "";
                        if (scaleText) {
                            subtext = `Kích thước: ${scaleText} | Công nghệ: ${printStyleText}`;
                        } else {
                            subtext = `Công nghệ: ${printStyleText}`;
                        }

                        itemsToDraw.push({
                            type: 'logo',
                            title: title,
                            subtext: subtext,
                            imgElement: logo.imgElement
                        });
                    });
                    
                    patterns.forEach((pattern, idx) => {
                        itemsToDraw.push({
                            type: 'pattern',
                            title: `Họa Tiết Toàn Thân: ${pattern.angle}`,
                            subtext: `Scale: ${pattern.scale}% | Opacity: ${pattern.opacity}% | Kiểu in: ${pattern.printType === 'chuyen-nhiet' ? 'In chuyển nhiệt' : 'In kỹ thuật số'}`,
                            imgElement: pattern.imgElement
                        });
                    });

                    texts.forEach((text, idx) => {
                        const angleNames = { 'front': 'Mặt trước', 'back': 'Mặt sau', 'left': 'Cạnh trái', 'right': 'Cạnh phải' };
                        const typeNames = { 'straight': 'Chữ thẳng', 'curved': 'Chữ cong', 'circle': 'Chữ chạy tròn', 'vertical': 'Chữ dọc' };
                        itemsToDraw.push({
                            type: 'text',
                            title: `Chữ: "${text.content}" (${angleNames[text.view] || text.view})`,
                            subtext: `Kiểu: ${typeNames[text.type] || text.type} | Font: ${text.fontFamily} | Cỡ: ${text.fontSize}px`,
                            imgElement: text.imgElement
                        });
                    });

                    const visibleItems = itemsToDraw.slice(0, 4);
                    visibleItems.forEach((item, idx) => {
                        const rowY = 232 + (idx * 11);

                        // Thumbnail Box
                        pdf.setFillColor(255, 255, 255);
                        pdf.setLineWidth(0.15);
                        setPdfDrawColor('#d9e2ec');
                        pdf.roundedRect(98, rowY, 9, 9, 1, 1, 'FD');

                        if (item.imgElement) {
                            const imgW = item.imgElement.naturalWidth || 100;
                            const imgH = item.imgElement.naturalHeight || 100;
                            const fitThumb = fitImageInsideBox(imgW, imgH, 8, 8);
                            pdf.addImage(item.imgElement, 'PNG', 98 + 0.5 + fitThumb.x, rowY + 0.5 + fitThumb.y, fitThumb.w, fitThumb.h);
                        }

                        // Item details text
                        drawText(pdf, item.title, 109, rowY + 3.5, { bold: true, fontSize: 6.5, color: '#0f172a', maxWidth: 88 });
                        drawText(pdf, item.subtext, 109, rowY + 7.2, { fontSize: 6, color: '#64748b', maxWidth: 88 });
                    });
                }


                // ── 6. FOOTER BLOCK (y: 282 to 290) ───────────────────────────
                pdf.setLineWidth(0.15);
                setPdfDrawColor('#cbd5e1');
                pdf.setLineDashPattern([1, 1], 0);
                pdf.line(10, 281.5, 200, 281.5);
                pdf.setLineDashPattern([], 0); // Restore solid lines

                drawText(pdf, "Thiết kế & Sản xuất bởi Mrs Linh Uniform  |  Hotline: 0934 975 913  |  www.inaodongphucmrslinh.com", 105, 286.5, { fontSize: 7.2, color: '#64748b', align: 'center' });

                // Page Number Pill indicator
                pdf.setFillColor(224, 242, 254);
                pdf.roundedRect(188, 283.5, 12, 4, 1.2, 1.2, 'F');
                drawText(pdf, "Trang 1/1", 194, 286.5, { bold: true, fontSize: 6.2, color: '#0284c7', align: 'center' });

                // Custom naming structure: bang-mo-ta-san-pham-[ma-ho-so]-[ten-khach].pdf
                const cleanName = (designData.fullname || 'khach-hang')
                    .normalize('NFD')
                    .replace(/[\u0300-\u036f]/g, '') // remove Vietnamese accents
                    .replace(/đ/g, 'd').replace(/Đ/g, 'D') // convert đ/Đ
                    .replace(/[^a-zA-Z0-9]/g, '-') // replace non-alphanumeric with hyphens
                    .replace(/-+/g, '-') // normalize multiple hyphens
                    .replace(/^-|-$/g, ''); // strip leading/trailing hyphens
                const recordCode = designData.recordCode || '810834';
                const filename = `bang-mo-ta-san-pham-${recordCode}-${cleanName}.pdf`;
                pdf.save(filename);
                resolve();
            } catch (err) {
                reject(err);
            }
        });
    };
})();
